WITH agg AS (SELECT p.p_promo_sk, p.p_promo_name, CASE WHEN p.p_channel_catalog = 'Y' THEN 'Catalog' ELSE 'Other' END AS channel_type, SUM(cs.cs_net_profit) AS total_profit, SUM(cr.cr_fee) AS total_fee, SUM(cs.cs_net_profit) - SUM(cr.cr_fee) AS net_after_fee, MIN(t_return.t_time) - MIN(t_sale.t_time) AS min_time_diff_seconds FROM promotion p JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number AND cr.cr_item_sk = cs.cs_item_sk JOIN time_dim t_sale ON cs.cs_sold_time_sk = t_sale.t_time_sk JOIN time_dim t_return ON cr.cr_returned_time_sk = t_return.t_time_sk WHERE p.p_promo_id LIKE 'PROMO_%' GROUP BY p.p_promo_sk, p.p_promo_name, CASE WHEN p.p_channel_catalog = 'Y' THEN 'Catalog' ELSE 'Other' END) SELECT agg.p_promo_sk, agg.p_promo_name, agg.channel_type, agg.total_profit, agg.total_fee, agg.net_after_fee, agg.min_time_diff_seconds, ROW_NUMBER() OVER (PARTITION BY agg.channel_type ORDER BY agg.net_after_fee DESC) AS channel_net_rank FROM agg ORDER BY agg.net_after_fee DESC LIMIT 10
